@pytest.fixture
def cache_module():
 assert importlib.util.find_spec('backend.lab.evaluation_cache') is not None,'Verified job-scoped evaluation cache is not implemented'
 return importlib.import_module('backend.lab.evaluation_cache')

@pytest.fixture
def owned(tmp_path,cache_module):
 source=tmp_path/'owned-source.bin';source.write_bytes(b'owned verification bytes'*5000)
 frame=prepare(normalize(minute_frame('2026-11-04'))[0]);calls=[]
 def load():calls.append(1);return frame.copy(deep=True),[]
 return cache_module,source,hashlib.sha256(source.read_bytes()).hexdigest(),frame,calls,load


def test_prepared_reuse_retains_values_and_verifies_current_same_length_bytes(owned):
 module,path,digest,frame,calls,load=owned;cache=module.EvaluationCache(path.parent)
 first=cache.prepared(('window',),path,digest,load);second=cache.prepared(('window',),path,digest,load)
 pd.testing.assert_frame_equal(first[0],frame);pd.testing.assert_frame_equal(second[0],frame);assert len(calls)==1
 raw=path.read_bytes();path.write_bytes(b'X'+raw[1:]);assert len(path.read_bytes())==len(raw)
 with pytest.raises(DataError):cache.prepared(('window',),path,digest,load)
 assert len(calls)==1


