@pytest.mark.parametrize('timeframe',list(TIMEFRAMES))
def test_each_base_chart_matches_uncached_values_and_is_reused(owned,monkeypatch,timeframe):
 module,path,digest,frame,calls,load=owned;cache=module.EvaluationCache(path.parent);regular,_=cache.prepared(('window',),path,digest,load);provider=cache.provider(regular);assert provider is not None
 expected=aggregate(frame,timeframe);first=provider('SPY',timeframe);pd.testing.assert_frame_equal(first,expected)
 def forbidden(*a,**k):raise AssertionError('Cached base chart was recomputed')
 monkeypatch.setattr(module,'aggregate',forbidden);pd.testing.assert_frame_equal(provider('SPY',timeframe),expected)
 assert 0<cache.cache_bytes<=cache.max_bytes

@pytest.mark.parametrize('budget',[0,1])
def test_disabled_or_oversized_cache_falls_back_without_input_rejection(owned,budget):
 module,path,digest,frame,calls,load=owned;cache=module.EvaluationCache(path.parent,max_bytes=budget)
 for _ in range(2):
  regular,_=cache.prepared(('window',),path,digest,load);pd.testing.assert_frame_equal(regular,frame);assert cache.provider(regular) is None
 assert len(calls)==2 and cache.cache_bytes==0


def test_lru_eviction_keeps_accounted_bytes_bounded(owned):
 module,path,digest,frame,calls,load=owned;budget=int(frame.memory_usage(index=True,deep=True).sum()*1.5)+2048;cache=module.EvaluationCache(path.parent,max_bytes=budget)
 for key in [('one',),('two',),('one',)]:
  cache.prepared(key,path,digest,load);assert cache.cache_bytes<=budget
 assert len(calls)==3
 cache.clear();assert cache.cache_bytes==0 and cache.provider(frame) is None


def test_context_isolates_roots_threads_nested_scopes_and_exception_cleanup(owned):
 module,path,digest,frame,calls,load=owned;assert module.current_cache(path.parent) is None
 with module.evaluation_cache(path.parent) as outer:
  outer.prepared(('window',),path,digest,load);assert module.current_cache(path.parent) is outer and module.current_cache(path.parent/'other') is None
  with ThreadPoolExecutor(max_workers=1) as executor:
   assert executor.submit(module.current_cache,path.parent).result() is None
   context=copy_context();assert executor.submit(context.run,module.current_cache,path.parent).result() is None
  with pytest.raises(RuntimeError):
   with module.evaluation_cache(path.parent) as inner:
    assert inner is not outer and module.current_cache(path.parent) is inner
    inner.prepared(('window',),path,digest,load);raise RuntimeError('Owned exit fault')
  assert inner.cache_bytes==0 and module.current_cache(path.parent) is outer
 assert outer.cache_bytes==0 and module.current_cache(path.parent) is None

