def test_actual_lab_complete_cached_report_matches_uncached_and_guard_precedes_reuse(client_lab,cache_module,monkeypatch):
 from backend.lab import service
 client,lab=client_lab;manifest=seed(lab);request=payload(manifest);cfg=Strategy(**request['strategy']);costs=Costs(**request['costs']);portfolio=Portfolio(**request['portfolio']);args=(manifest['id'],cfg,costs,portfolio,request['start'],request['end'])
 original_loader=service.load_window;calls=[]
 def counted(*a,**k):calls.append(1);return original_loader(*a,**k)
 monkeypatch.setattr(service,'load_window',counted);expected=lab.evaluate(*args)
 with cache_module.evaluation_cache(lab.root):
  assert lab.evaluate(*args)==expected and lab.evaluate(*args)==expected
  assert len(calls)==2
  def protected(*a,**k):raise StateError('Owned protected-date rejection')
  monkeypatch.setattr(lab.guard,'access',protected)
  with pytest.raises(StateError,match='protected-date'):lab.evaluate(*args)
  assert len(calls)==2
 assert cache_module.current_cache(lab.root) is None

