def test_streamed_integrity_uses_bounded_reads_and_cancels_during_large_hash(owned,monkeypatch):
 module,path,digest,frame,calls,load=owned;original=Path.open;sizes=[]
 class Reader:
  def __init__(self,stream):self.stream=stream
  def read(self,n=-1):assert 0<n<=65536;sizes.append(n);return self.stream.read(n)
  def __enter__(self):return self
  def __exit__(self,*args):self.stream.close()
 def instrument(target,*args,**kwargs):
  stream=original(target,*args,**kwargs)
  return Reader(stream) if target==path and args and args[0]=='rb' else stream
 with monkeypatch.context() as patch:
  patch.setattr(Path,'open',instrument);cache=module.EvaluationCache(path.parent);cache.prepared(('stream',),path,digest,load)
 assert sizes and max(sizes)==65536
 large=path.parent/'owned-large-source.bin'
 with large.open('wb') as stream:
  for _ in range(65):stream.write(bytes(1024*1024))
 count=[]
 def cancel():count.append(1);return len(count)==2
 cache=module.EvaluationCache(path.parent,cancel=cancel)
 with pytest.raises(InterruptedError):cache.prepared(('large',),large,'0'*64,load)
 assert len(count)==2 and len(calls)==1


def test_manifest_race_during_actual_loading_rejects_before_caching(client_lab,cache_module,monkeypatch):
 from backend.lab import service
 client,lab=client_lab;manifest=seed(lab);request=payload(manifest);original=service.load_window
 def changed(*args,**kwargs):
  frame,loaded=original(*args,**kwargs);return frame,loaded|dict(owned_race='changed')
 monkeypatch.setattr(service,'load_window',changed)
 with cache_module.evaluation_cache(lab.root) as cache:
  with pytest.raises(DataError,match='manifest changed during'):lab.evaluate(manifest['id'],Strategy(**request['strategy']),Costs(**request['costs']),Portfolio(**request['portfolio']),request['start'],request['end'])
  assert cache.cache_bytes==0
